import {roster} from './native-roster-synthetic.js';
import {proof,CONTRACT} from './employment-adoption-history-synthetic.js';
export function currentProof(kind='hire'){const p=proof();return{version:'native-employee-read.v1',scope:p.scope,contract:{...p.contract,recordKind:kind,...(kind==='hire'?{legajo:'5001',startDate:'2026-09-01',status:'active'}:{})}};}
export function currentSnapshot(total=57,patch={}){return{version:'native-directory-snapshot.v1',scope:proof().scope,total,imported:0,token:'a'.repeat(64),...patch};}
export function currentRoster(){const v=roster();return{...v,version:'native-roster.v2',scope:{tenantId:proof().scope.tenantId,membershipId:proof().scope.membershipId,bindingId:proof().scope.bindingId,companyId:101},counts:{active:55,pending_start:0,inactive:1,state_error:0,unknown:1},rows:v.rows.map((r,i)=>({...r,recordKind:i<3?'adopted':'hire',...(i===0?{legajo:'A/07',name:null,dni:null,cuil:null,birthDate:null,startDate:null,status:'unknown'}:i===1?{birthDate:'1850-01-01',startDate:'1888-01-01'}:i===2?{endDate:'2026-09-01',status:'inactive'}:{})}))};}
export function directoryRows(total=57){return[{__total:total,__scope:{totalContracts:total,totalPeople:total,activeContracts:55,activePeople:55,inactiveContracts:1,unknownContracts:1,matched:0,ambiguous:0,unmatched:0},__sourceCutoffFrom:null,__sourceCutoffTo:null,__sectors:[],__organizations:[],__agreements:[],__pageOrder:1,contractId:CONTRACT,recordOrigin:'MUNICONTROL',nombre:'PERSONA SINTÉTICA',legajo:'A/07',activo:false,administrativeStatus:'unknown'}];}
